 "content": "from collections import Counter


def transform(grid):
    """Encode the patterned panel's rare cells as 3, except at marker cells."""
    h, w = len(grid), len(grid[0])
    panels = None
    markers = None
    # Split at a centered full-width or full-height solid line.
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            panels = (grid[:r], grid[r + 1:])
            markers = grid[:r]
            break
    if panels is None:
        for c in range(1, w - 1):
            if all(row[c] == grid[0][c] for row in grid) and c == w - c - 1:
                panels = ([row[:c] for row in grid], [row[c + 1:] for row in grid])
                markers = [row[:c] for row in grid]
                break
    if panels is None:
        raise ValueError("expected centered full separator")

    a, b = panels

    def dominant(panel):
        return Counter(v for row in panel for v in row).most_common(1)[0][0]

    bg_a, bg_b = dominant(a), dominant(b)
    marker_color = next((v for row in a for v in row if v != bg_a), None)
    # The second panel is the patterned field; its color matching the first
    # panel's background is the sparse pattern, while the dominant color is background.
    rare_b = next((v for row in b for v in row if v != bg_b), None)
    if rare_b is None:
        return [[bg_a for _ in row] for row in b]
    out = []
    for r, row in enumerate(b):
        out_row = []
        for c, value in enumerate(row):
            if value == bg_b:
                out_row.append(bg_a)
            elif value == rare_b:
                out_row.append(bg_a if markers[r][c] == marker_color else 3)
            else:
                out_row.append(value)
        out.append(out_row)
    return out


